# intersection checking
def segments_intersect(p1, p2, p3, p4):
    """
    Check if line segment p1-p2 intersects with p3-p4.
    Uses cross product method for robust intersection detection.
    Points are (x, y). We consider only proper intersection (not at endpoints).
    """
    def cross_product(a, b, c):
        return (b[0] - a[0]) * (c[1] - a[1]) - (b[1] - a[1]) * (c[0] - a[0])

    d1 = cross_product(p3, p4, p1)
    d2 = cross_product(p3, p4, p2)
    d3 = cross_product(p1, p2, p3)
    d4 = cross_product(p1, p2, p4)

    # Check if the endpoints are on opposite sides of the other line
    if ((d1 > 0 and d2 < 0) or (d1 < 0 and d2 > 0)) and \
       ((d3 > 0 and d4 < 0) or (d3 < 0 and d4 > 0)):
        return True

    return False


def is_valid_matching(spaceships, bases, matching):
    """
    Check if the matching has any intersecting segments.
    matching is a list where matching[i] is the index of the base matched to spaceship i.
    """
    for i in range(len(spaceships)):
        for j in range(i + 1, len(spaceships)):
            if matching[i] != matching[j] and segments_intersect(
                spaceships[i], bases[matching[i]],
                spaceships[j], bases[matching[j]]
            ):
                return False
    return True


