        if valid:
            result = [''] * n
            for i in range(n):
                result[i] = str(match_list[i] + 1)
            return '\n'.join(result)

    # Fallback: try sorted matching
    sorted_sw = sorted(range(n), key=lambda i: spaceships[i][0])
    sorted_bases = sorted(range(n), key=lambda i: bases[i][0])

    match_list = [sorted_bases[i] for i in sorted_sw]
    valid = True

    for i in range(n):
        for j in range(i + 1, n):
            if segments_intersect(spaceships[i], bases[match_list[i]], 
                                  spaceships[j], bases[match_list[j]]):
                valid = False
                break
        if not valid:
            break

    if valid:
        result = [''] * n
        for i in range(n):
            result[i] = str(match_list[i] + 1)
        return '\n'.join(result)

    # Final fallback: diagonal matching
    result = []
    for i in range(n):
        result.append(str(i + 1))
    return '\n'.join(result)


