def solution(input_str):
    lines = input_str.strip().split('\n')
    n = int(lines[0])
    a = list(map(int, lines[1].split()))

    # Find empty positions (1-indexed)
    empty_positions = []
    for i in range(n):
        if a[i] == -1:
            empty_positions.append(i + 1)  # 1-indexed position

    m = len(empty_positions)

    # Find available values
    used_values = set()
    for val in a:
        if val != -1:
            used_values.add(val)

    available_values = set(range(1, n + 1)) - used_values

    # Count how many empty positions have matching available values (these are "bad" positions)
    k = 0
    for pos in empty_positions:
        if pos in available_values:
            k += 1

    MOD = 1000000007

    # Precompute factorials and their modular inverses
    max_fact = max(m, k) + 1
    fact = [1] * (max_fact + 1)
    invFact = [1] * (max_fact + 1)

    for i in range(1, max_fact + 1):
        fact[i] = (fact[i - 1] * i) % MOD

    invFact[max_fact] = pow(fact[max_fact], MOD - 2, MOD)
    for i in range(max_fact - 1, -1, -1):
        invFact[i] = (invFact[i + 1] * (i + 1)) % MOD

    def nCr_mod(n, r):
        if r < 0 or r > n:
            return 0
        return fact[n] * invFact[r] % MOD * invFact[n - r] % MOD

    # Use inclusion-exclusion principle to count derangements
    # Sum_{i=0 to k} (-1)^i * C(k, i) * (m-i)!
    result = 0
    for i in range(k + 1):
        term = nCr_mod(k, i) * fact[m - i] % MOD
        if i % 2 == 1:
            result = (result - term + MOD) % MOD
        else:
            result = (result + term) % MOD

    return str(result) + '\n'

