    # Identify all change events and their positions
    change_positions = []
    for i, (etype, val) in enumerate(events):
        if etype == 'CHANG':
            change_positions.append(i)

    # Track visit intervals for each friend
    # visit_intervals[friend_name] = list of (start, end) tuples
    # where interval is [start, end) in events list
    from collections import defaultdict
    visit_intervals = defaultdict(list)

    current_interval_start = 0
    current_handle = None

    for i, (etype, x) in enumerate(events):
        if etype == 'CHANG':
            # Save the current visit interval if it exists
            if current_handle is not None and len(visit_intervals.get(current_handle, [])) > 0:
                pass  # intervals will be tracked per friend in next pass
            current_handle = None
            current_interval_start = i
        else:
            visitor = x
            # Track this visit for this visitor
            # The visit happens between current_interval_start and next CHANG
            if visitor not in visit_intervals:
                visit_intervals[visitor] = []
            visit_intervals[visitor].append((current_interval_start, i + 1))
            # Only update if we're tracking that specific visitor's handle
            if current_handle == visitor:
                current_handle = visitor
            elif current_handle is None:
                current_handle = visitor

    # Each friend's visits in their respective intervals
    # Build conflict graph

    friend_names=set()
    for etype, val in events:
        if etype == 'VISIT':
            friend_names.add(val)

    friends = list(friend_names)
    friend_idx = {name: i for i, name in enumerate(friends)}
    num_friends = len(friends)

    def overlaps(f1, f2, intervals, idxs):
        """Check if friend f1 and f2's visits ever overlap in the same interval"""
        i1 = idxs[f1]
        i2 = idxs[f2]

        # Get all intervals for each friend
        intervals1 = intervals[f1]
        intervals2 = intervals[f2]

        for (s1, e1) in intervals1:
            for (s2, e2) in intervals2:
                # Check if these two intervals have any overlap
                if max(s1, s2) < min(e1, e2):
                    return True
        return False

    # Build conflict graph: adj[i] contains j if friends i and j conflict
    adj = [[] for _ in range(num_friends)]

    for i in range(num_friends):
        for j in range(i + 1, num_friends):
            if overlaps(friends[i], friends[j], visit_intervals, friend_idx):
                adj[i].append(j)
                adj[j].append(i)

    # Find maximum independent set on this conflict graph
    # Maximize number of non-adjacent vertices

    max_size = 0

    # Try all subsets (feasible since m <= 40, but we'll use pruning)
    for mask in range(1 << num_friends):
        cnt = 0
        valid = True
        for i in range(num_friends):
            if not (mask & (1 << i)):
                continue
            cnt += 1
            for j in range(i + 1, num_friends):
                if not (mask & (1 << j)):
                    continue
                # Check if i and j are connected (conflict)
                if j in adj[i]:
                    valid = False
                    break
            if not valid:
                break

        if valid:
            max_size = max(max_size, cnt)

    return str(max_size)

