    reachable = {0}

    for step, (t, x, y) in enumerate(ops):
        next_reachable = set()
        for k in reachable:
            current = k
            # Apply the operation 0 to y times
            for a in range(y + 1):
                if current > m:
                    break
                next_reachable.add(current)
                if a < y:
                    if t == 1:
                        current = math.ceil(current + x)
                    else:
                        current = math.ceil(current * x)
        reachable = next_reachable

        for j in range(1, m + 1):
