def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m, k, p = map(int, lines[0].split())

    bamboos = []
    for i in range(1, n + 1):
        h, a = map(int, lines[i].split())
        bamboos.append((h, a))

    # Total hammer uses available across m days
    total_hits_limit = k * m

    def can_achieve(H):
        """Check if maximum height H is achievable."""
        total_hits_needed = 0
        for h, a in bamboos:
            # Final height without any hits
            final_height = h + m * a
            if final_height > H:
                # Calculate minimum hits needed to reduce this to H
                threshold = final_height - H
                hits_needed = (threshold + p - 1) // p  # ceiling division
                total_hits_needed += hits_needed
                if total_hits_needed > total_hits_limit:
                    return False
        return True

    if not bamboos:
        return '0'

    # Binary search for minimum H
    low = 0
    high = max(h + m * a for h, a in bamboos) + 1

    while low < high:
        mid = (low + high) // 2
        if can_achieve(mid):
            high = mid
        else:
            low = mid + 1

    return str(low)

