    """Check if diagonal (i, j) lies inside a simple polygon"""
    if i == j:
        return False
    if abs(i - j) == 1:
        return True  # This is a polygon edge
    if i == 0 and j == n - 1:
        return True  # Edge case for closing polygon

    # Check if diagonal intersects any polygon edge (other than at endpoints)
    for k in range(n):
        k2 = (k + 1) % n
        if k == i or k == j or k2 == i or k2 == j:
