    for i in range(1, m + 1):
        if i < len(lines):
            u, v = map(int, lines[i].split())
            adj[u].append(v)

    # BFS from each vertex to compute all-pairs shortest paths
    dist = [[-1] * (n + 1) for _ in range(n + 1)]
    for start in range(1, n + 1):
        queue = deque([start])
        dist[start][start] = 0
        while queue:
            u = queue.popleft()
            for v in adj[u]:
                if dist[start][v] == -1:
                    dist[start][v] = dist[start][u] + 1
                    queue.append(v)

    max_total = -1
    best = (1, 1, 1, 1)

    # Iteration over middle pair (b, c)
    for b in range(1, n + 1):
        for c in range(1, n + 1):
            if b == c:
                continue
            if dist[b][c] == -1:
                continue

            dbc = dist[b][c]

            # Find best a (farness from b, a != b,c)
            best_a = None
            best_a_dist = -1
            forbidden = {b, c}

            for i in range(1, n + 1):
                if i not in forbidden and dist[i][b] != -1:
                    if dist[i][b] > best_a_dist:
                        best_a = i
                        best_a_dist = dist[i][b]

            if best_a is None:
                continue

            # Find best d (farness from c, d != c, best_a)
            best_d = None
            best_d_dist = -1
            forbidden = {c, best_a}

            for i in range(1, n + 1):
                if dist[c][i] != -1 and i not in forbidden:
                    if dist[c][i] > best_d_dist:
                        best_d_dist = dist[c][i]
                        best_d = i

            if best_d is None:
                continue

            # Check if best_a == best_d (impossible since forbidden set excludes both)
