    import math

    def circumradius(A, B, C):
        # Calculate area using determinant method: |x1(y2-y3) + x2(y3-y1) + x3(y1-y2)| / 2
        area_det = A[0] * (B[1] - C[1]) + B[0] * (C[1] - A[1]) + C[0] * (A[1] - B[1])
        abs_area_det = abs(area_det)

        if abs_area_det == 0:
            return float('inf')  # Collinear points, no triangle

        # Using formula: r = (a*b*c) / (4*Area)
        # Since Area = |det|/2, 4*Area = 2*|det|
        def dist_sq(P, Q):
            return (P[0] - Q[0])**2 + (P[1] - Q[1])**2

        a_sq = dist_sq(B, C)
        b_sq = dist_sq(A, C)
        c_sq = dist_sq(A, B)

        return math.sqrt(a_sq * b_sq * c_sq) / (2 * abs_area_det)

    # Find the minimum circumradius among all triangles
    # The last hole disappears at the minimum circumradius (when the smallest hole gets filled)
    min_r = float('inf')
    found = False

    for i in range(n):
        for j in range(i + 1, n):
            for k in range(j + 1, n):
                A, B, C = centers[i], centers[j], centers[k]
                r = circumradius(A, B, C)
                if r < min_r:
                    min_r = r
                found = True

    if not found:
        return "-1\n"

    return f"{min_r:.6f}\n"


