        r, n = map(int, lines[i].split())
        queries.append((r, n))
        all_n[n] = max(all_n.get(n, 0), r + 1)

    MAX_N = max(all_n.keys(), default=1) + 1

    # Sieve
    spf = list(range(MAX_N))
    for i in range(2, int(MAX_N**0.5) + 1):
        if spf[i] == i:
            for j in range(i*i, MAX_N, i):
                if spf[j] == j:
                    spf[j] = i

    # Precompute distinct prime count and f0
    f0 = [0] * MAX_N
    for n in range(1, MAX_N):
        cnt = 0
        m = n
        while m > 1:
            cnt += 1
            m //= spf[m]
        f0[n] = (1 << cnt) % mod

    # Memoization
    cache = {}

    def compute(r, n):
        if n == 1:
            return 1
        if r == 0:
            return f0[n]
        if (r, n) in cache:
            return cache[(r, n)]

        res = 0
        for i in range(1, int(n**0.5) + 1):
            if n % i == 0:
                res = (res + compute(r - 1, i) * compute(r - 1, n // i)) % mod

        cache[(r, n)] = res
        return res

    results = []
    for r, n in queries:
        results.append(str(compute(r, n)))

    return '\n'.join(results)
